package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DroppedCountVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property dropped count of observed source ")
  void test_dropped_count_v_o_builder() {
    Assertions.assertFalse(DroppedCountVO.nullValue().getDroppedCount().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(DroppedCountVO.tryFrom(null).getDroppedCount().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, DroppedCountVO.from(1).getDroppedCount().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DroppedCountVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", DroppedCountVO.from(1).toString());
  }
}
